fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(8, 60 * 8);
        host::display::state_set(9, 40);
        host::display::state_set(10, (w / 2 - 20) * 8);
        host::display::state_set(11, 0);
        host::display::state_set(12, (w / 2 + 20) * 8);
        host::display::state_set(13, 0);
    }
    let mut x = [0; 3];
    let mut v = [0; 3];
    let mut i: i32 = 0;
    while i < 3 {
        x[i] = host::display::state_get(8 + i * 2);
        v[i] = host::display::state_get(9 + i * 2);
        i = i + 1;
    }
    i = 0;
    while i < 3 {
        x[i] = x[i] + v[i];
        if x[i] < 20 * 8 { x[i] = 20 * 8; v[i] = -v[i]; }
        if x[i] > (w - 20) * 8 { x[i] = (w - 20) * 8; v[i] = -v[i]; }
        i = i + 1;
    }
    i = 0;
    while i < 2 {
        if x[i + 1] - x[i] < 224 {
            let tmp: i32 = v[i];
            v[i] = v[i + 1];
            v[i + 1] = tmp;
            let mid: i32 = (x[i] + x[i + 1]) / 2;
            x[i] = mid - 112;
            x[i + 1] = mid + 112;
        }
        i = i + 1;
    }
    i = 0;
    while i < 3 {
        host::display::state_set(8 + i * 2, x[i]);
        host::display::state_set(9 + i * 2, v[i]);
        i = i + 1;
    }
    host::display::clear(0x101014);
    let ty: i32 = h / 2;
    host::display::fill_rect(0, ty + 14, w, 3, 0x404048);
    let pal: [i32; 3] = [0xe05040, 0x40c060, 0x5080e0];
    i = 0;
    while i < 3 {
        host::display::fill_rect(x[i] / 8 - 14, ty - 14, 28, 28, pal[i]);
        host::display::fill_rect(x[i] / 8 - 8, ty - 8, 8, 8, 0xffffff);
        i = i + 1;
    }
    host::display::draw_string(8, 8, "EQUAL MASS = SWAP V", 0x707070, 1);
    host::display::present();
}
